      "value": "import json, re, datetime
vars['route'] = 'technical_hold'
vars['speech'] = 'I could not complete that action. I do not have any further information.'
try:
    def unpack(v, default):
        if isinstance(v, str):
            try:
                v = json.loads(v)
            except Exception:
                return default
        return v if isinstance(v, type(default)) else default
    s = unpack(vars.get('call_state'), {})
    for key, value in dict(phase='name', name_asks=0, wrong=0, declines=0, no_talk=0, human_asked=False, callback_invalid=0, products=[], loaded=False, notice='').items():
        s.setdefault(key, value)
    vars['call_state'] = s
    prefix = str(vars.get('pending_speech', ''))
    vars['pending_speech'] = ''
    now = datetime.datetime.fromisoformat(str(vars.get('now', '')).replace('Z', '+00:00'))
    today = now.date()
    holidays = set(['2026-10-26','2026-11-11','2026-11-26','2026-12-25','2027-01-01'])
    months = ['january','february','march','april','may','june','july','august','september','october','november','december']
    weekdays = ['monday','tuesday','wednesday','thursday','friday','saturday','sunday']
    def business(d):
        return d.weekday() < 5 and d.isoformat() not in holidays
    def next_business(d):
        while not business(d):
            d += datetime.timedelta(days=1)
        return d
    def after_business(d, n):
        while n:
            d += datetime.timedelta(days=1)
            if business(d):
                n -= 1
        return d
    def week_offer():
        d = today + datetime.timedelta(days=4-today.weekday())
        while not business(d):
            d -= datetime.timedelta(days=1)
        if d <= today:
            d = today + datetime.timedelta(days=11-today.weekday())
            while not business(d):
                d -= datetime.timedelta(days=1)
        return d
    def amount(v):
        t = str(v).strip().replace(',', '')
        if not re.fullmatch(r'[0-9]+(?:\.[0-9]+)?', t):
            raise ValueError('amount')
        n = float(t)
        if n != n or abs(n) == float('inf'):
            raise ValueError('amount')
        return n
    def money(v):
        n = float(v)
        if n != n or abs(n) == float('inf'):
            raise ValueError('amount')
        if n == int(n):
            return format(int(n), ',')
        t = str(n)
        if '.' in t and 'e' not in t.lower():
            a, b = t.split('.')
            return format(int(a), ',') + '.' + b
        return t
    def date_speech(v):
        d = datetime.date.fromisoformat(str(v))
        return str(d.day) + ' ' + months[d.month-1].title() + ' ' + str(d.year)
    def parse_date(raw, context=''):
        original = str(raw).strip()
        if not original:
            return 'missing', '', context
        if re.fullmatch(r'\d{4}-\d{2}-\d{2}', original):
            try:
                return 'exact', datetime.date.fromisoformat(original).isoformat(), context
            except Exception:
                return 'invalid', '', context
        t = original.lower().replace('-', ' ').replace(',', ' ')
        t = re.sub(r'\s+', ' ', t).strip()
        for i, name in enumerate(months):
            aliases = [name[:3]] + (['sept'] if i == 8 else [])
            for alias in aliases:
                t = re.sub(r'\b' + alias + r'\b\.?', name, t)
        for name in weekdays:
            t = re.sub(r'\b' + name[:3] + r'\b\.?', name, t)
        ords = ['first','second','third','fourth','fifth','sixth','seventh','eighth','ninth','tenth','eleventh','twelfth','thirteenth','fourteenth','fifteenth','sixteenth','seventeenth','eighteenth','nineteenth','twentieth','twenty first','twenty second','twenty third','twenty fourth','twenty fifth','twenty sixth','twenty seventh','twenty eighth','twenty ninth','thirtieth','thirty first']
        cards = ['zero','one','two','three','four','five','six','seven','eight','nine','ten','eleven','twelve','thirteen','fourteen','fifteen','sixteen','seventeen','eighteen','nineteen','twenty','twenty one','twenty two','twenty three','twenty four','twenty five','twenty six','twenty seven','twenty eight','twenty nine','thirty','thirty one']
        conversions = [(word, i+1) for i, word in enumerate(ords)] + [(word, i) for i, word in enumerate(cards)]
        for word, number in sorted(conversions, key=lambda item: len(item[0]), reverse=True):
            t = re.sub(r'\b' + word + r'\b', str(number), t)
        t = re.sub(r'(\d+)(?:st|nd|rd|th)\b', r'\1', t)
        if t in ['today','this day']:
            return 'exact', today.isoformat(), context
        if t in ['tomorrow','the next day']:
            return 'exact', (today + datetime.timedelta(days=1)).isoformat(), context
        if t in ['day after tomorrow','the day after tomorrow']:
            return 'exact', (today + datetime.timedelta(days=2)).isoformat(), context
        m = re.fullmatch(r'(?:in )?(\d+) days?(?: from today| from now)?', t)
        if m:
            return 'exact', (today + datetime.timedelta(days=int(m.group(1)))).isoformat(), context
        m = re.fullmatch(r'(\d+) weeks? from (?:today|now)', t)
        if m:
            return 'exact', (today + datetime.timedelta(days=7*int(m.group(1)))).isoformat(), context
        monday = today - datetime.timedelta(days=today.weekday())
        weekday_hits = [i for i, word in enumerate(weekdays) if re.search(r'\b' + word + r'\b', t)]
        if len(weekday_hits) > 1:
            return 'ambiguous', '', context
        wd = weekday_hits[0] if weekday_hits else -1
        if wd >= 0 and re.fullmatch(r'(?:on )?(?:this|next) ' + weekdays[wd], t):
            return 'exact', (monday + datetime.timedelta(days=wd+(7 if 'next' in t else 0))).isoformat(), context
        if re.search(r'\b(?:next week|following week|week after this)\b', t):
            context = 'week:' + (monday + datetime.timedelta(days=7)).isoformat()
        elif 'this week' in t:
            context = 'week:' + monday.isoformat()
        elif re.search(r'\b(?:next|following) month\b', t):
            nm = (today.replace(day=28) + datetime.timedelta(days=4)).replace(day=1)
            context = 'month:' + nm.strftime('%Y-%m')
        elif re.search(r'\b(?:this month|the month|current month)\b', t):
            context = 'month:' + today.strftime('%Y-%m')
        m = re.fullmatch(r'(\d{1,2})[/.](\d{1,2})(?:[/.](\d{4}))?', t)
        if m:
            a, b = int(m.group(1)), int(m.group(2))
            y = int(m.group(3)) if m.group(3) else (int(context[6:10]) if context.startswith('month:') else today.year)
            candidates = []
            for day, month in [(a, b), (b, a)]:
                try:
                    d = datetime.date(y, month, day)
                    if d not in candidates:
                        candidates.append(d)
                except Exception:
                    pass
            if len(candidates) > 1 and context.startswith('month:'):
                candidates = [d for d in candidates if d.strftime('%Y-%m') == context[6:]]
            if len(candidates) == 1:
                return 'exact', candidates[0].isoformat(), 'month:' + candidates[0].strftime('%Y-%m')
            return 'ambiguous' if candidates else 'invalid', '', context
        month_hits = [i+1 for i, word in enumerate(months) if re.search(r'\b' + word + r'\b', t)]
        nums = [int(v) for v in re.findall(r'\b\d+\b', t)]
        years = [v for v in nums if v >= 1000]
        days = [v for v in nums if 1 <= v <= 31]
        if len(month_hits) > 1 or len(years) > 1:
            return 'ambiguous', '', context
        if month_hits:
            y = years[0] if years else (int(context[6:10]) if context.startswith('month:') else today.year)
            context = 'month:' + str(y) + '-' + str(month_hits[0]).zfill(2)
        if len(days) == 1:
            candidates = []
            if context.startswith('week:'):
                base = datetime.date.fromisoformat(context[5:])
                candidates = [base + datetime.timedelta(days=i) for i in range(7)]
                candidates = [d for d in candidates if d.day == days[0] and (not years or d.year == years[0])]
            elif context.startswith('month:'):
                y, m = [int(v) for v in context[6:].split('-')]
                try:
                    candidates = [datetime.date(years[0] if years else y, m, days[0])]
                except Exception:
                    return 'invalid', '', context
            if wd >= 0:
                candidates = [d for d in candidates if d.weekday() == wd]
            if len(candidates) == 1:
                return 'exact', candidates[0].isoformat(), context
            return 'ambiguous', '', context
        if days or years:
            return 'ambiguous', '', context
        if wd >= 0 and context.startswith('week:'):
            return 'exact', (datetime.date.fromisoformat(context[5:]) + datetime.timedelta(days=wd)).isoformat(), context
        if month_hits or re.search(r'\b(?:week|month|salary|wages|payday|paycheck|payroll|pension|sometime|someday|later|eventually|soon|around|when|once|after)\b', t):
            return 'period', '', context
        return 'ambiguous', '', context
    def defaults(p):
        for key, value in dict(status='open', attempts=0, floor_offered=False, too_much=False, vague_asked=False, date_context='', rejected=[], writes=0, confirmed=False, noted=False).items():
            p.setdefault(key, value)
    for p in s['products']:
        defaults(p)
    opening_text = 'I am a digital assistant calling from Freya Bank, and this call is recorded.'
    transcript = str(vars.get('system.conversation', ''))
    if opening_text.lower() in transcript.lower():
        s['opening_spoken'] = True
        if s['phase'] == 'name':
            s['name_asks'] = max(s['name_asks'], min(2, transcript.lower().count('am i speaking with')))
    def authorized():
        return all(vars.get(key) == 'yes' for key in ['security_ready','dob_verified','phone_verified'])
    def ready():
        return authorized() and s.get('loaded') is True and 1 <= len(s['products']) <= 3
    def problem():
        vars['route'] = 'technical_hold'
        vars['speech'] = 'I could not complete that action. I do not have any further information.'
    def emit(phase, text, target='identity_question'):
        global prefix
        s['phase'] = phase
        s['question'] = text
        vars['speech'] = prefix + text
        prefix = ''
        s['last_speech'] = vars['speech']
        vars['route'] = target
    def finish():
        global prefix
        ps = s['products']
        if s.get('transfer_requested') and not s.get('transfer_success'):
            problem()
            return
        if s.get('transfer_success'):
            outcome = 'transferred'
            reason = dict(general='human', support='support', restructuring='restructuring')[s['transfer_success']]
        elif s.get('early_outcome'):
            outcome, reason = s['early_outcome'], s.get('early_reason', '')
        else:
            if not ready() or any(p['status'] in ['open','pending'] for p in ps):
                problem()
                return
            for p in ps:
                if p['status'] != 'recorded' and not p['noted']:
                    vars['note_product'], vars['note_reason'] = p['product_id'], p['status']
                    vars['route'] = 'note_write'
                    return
            if any(p['status'] == 'recorded' for p in ps):
                outcome, reason = 'promise', ''
            elif all(p['status'] == 'paid' for p in ps):
                outcome, reason = 'paid', ''
            else:
                outcome, reason = 'no_promise', next(p['status'] for p in ps if p['status'] != 'paid')
        vars['close_outcome'], vars['close_reason'] = outcome, reason
        text = prefix + s.get('notice', '')
        prefix = ''
        if any(p['status'] == 'recorded' for p in ps):
            text += 'Your payment promise has been recorded. You will receive a text message confirming this promise. '
        vars['speech'] = text + 'Thank you. Goodbye.'
        vars['route'] = 'farewell'
    def early(outcome, reason):
        s['early_outcome'], s['early_reason'] = outcome, reason
        finish()
    def ask_name():
        if s['name_asks'] >= 2:
            early('not_reached', 'unclear')
        else:
            s['name_asks'] += 1
            emit('name', 'Am I speaking with ' + str(vars.get('title', '')) + ' ' + str(vars.get('last_name', '')) + '?')
    def ask_security():
        if vars.get('dob_verified') != 'yes':
            emit('dob', 'Please say the month of your birth as a word.' if s.get('month_word_required') else 'What is your date of birth?')
        else:
            emit('phone', 'What are the last four digits of the phone number on file?')
    def transfer(queue):
        s['transfer_requested'] = queue
        s.pop('ticket', None)
        vars['transfer_queue'] = queue
        vars['route'] = 'transfer_write'
    def human():
        if s['human_asked']:
            transfer('general')
            return
        s['human_asked'] = True
        s['resume_phase'], s['resume_speech'] = s['phase'], s.get('question', s.get('last_speech', ''))
        emit('human', 'May I try to help you first?', 'collection_question' if ready() else 'identity_question')
    def sig(a, d):
        return str(float(a)) + '|' + str(d)
    def base_terms(p, phase, focus):
        if p['status'] == 'pending':
            return p['amount'], p['date']
        if phase == 'offer' and s['products'][focus]['product_id'] == p['product_id']:
            return p.get('offer_amount', p['past_due']), p.get('offer_date', today.isoformat())
        return p['past_due'], today.isoformat()
    def reject(index, phase):
        p = s['products'][index]
        if p['status'] == 'recorded':
            return
        if phase == 'offer':
            a, d = p.get('offer_amount', p['past_due']), p.get('offer_date', today.isoformat())
        else:
            a, d = base_terms(p, phase, s.get('focus', index))
        value = sig(a, d)
        if value not in p['rejected']:
            p['rejected'].append(value)
        p['status'], p['confirmed'], p['vague_asked'] = 'open', False, False
        p.pop('amount', None)
        p.pop('date', None)
    def readback():
        ps = [p for p in s['products'] if p['status'] == 'pending']
        if not ps:
            finish()
            return
        for p in ps:
            p['confirmed'] = False
        s['readback_ids'] = [p['product_id'] for p in ps]
        text = ' '.join('For your ' + p['label'] + ', ' + money(p['amount']) + ' on ' + date_speech(p['date']) + '.' for p in ps)
        emit('confirm', text + ' Do you confirm?', 'collection_question')
    def offer(index):
        p = s['products'][index]
        s['focus'] = index
        if s.get('hardship'):
            if s.get('hardship_declined'):
                p['status'] = 'hardship'
                advance()
            else:
                emit('support', 'Would you like me to connect you with the customer support team?', 'collection_question')
            return
        p['status'], p['confirmed'] = 'open', False
        while p['attempts'] < p['budget']:
            p['attempts'] += 1
            a = p['floor'] if p['attempts'] == 2 or p['too_much'] else p['past_due']
            d = p['deadline'] if p['attempts'] == 2 else week_offer().isoformat()
            if sig(a, d) in p['rejected']:
                continue
            p['offer_amount'], p['offer_date'] = a, d
            text = ''
            if a < p['past_due']:
                p['floor_offered'] = True
                text = 'The rest stays overdue. '
            emit('offer', text + 'Can you pay ' + money(a) + ' for your ' + p['label'] + ' on ' + date_speech(d) + '?', 'collection_question')
            return
        p['status'] = 'refused'
        advance()
    def advance():
        for i, p in enumerate(s['products']):
            if p['status'] == 'open':
                offer(i)
                return
        readback()
    def resolve(ref, kind, phase, focus, readback_ids):
        ps = s['products']
        t = re.sub(r'[^a-z0-9 ]', ' ', str(ref).lower())
        t = re.sub(r'\s+', ' ', t).strip()
        if t in ['all','both','everything','all of them','all products','all three','the lot']:
            return list(range(len(ps)))
        if not t:
            if len(ps) == 1:
                return [0]
            if phase == 'confirm':
                ids = [i for i, p in enumerate(ps) if p['product_id'] in readback_ids]
                return ids if len(ids) == 1 else []
            if phase == 'all' and kind == 'promise':
                return list(range(len(ps)))
            if phase == 'offer':
                return [focus]
            return []
        simple = re.sub(r'\b(?:my|the|our|that|this)\b', '', t)
        simple = re.sub(r'\s+', ' ', simple).strip()
        hits = []
        for i, p in enumerate(ps):
            hit = t == str(p['product_id']).lower() or t == p.get('label', '').lower()
            if p.get('type') == 'credit_card' and re.search(r'\b(?:card|credit)\b', t):
                suffixes = re.findall(r'\b\d{4}\b', t)
                hit = not suffixes or p.get('card_last4') in suffixes
            if p.get('type') == 'personal_loan' and re.search(r'\bpersonal\b', t):
                hit = True
            if p.get('type') == 'car_loan' and re.search(r'\b(?:car|auto|vehicle)\b', t):
                hit = True
            if simple == 'loan' and p.get('type') in ['personal_loan','car_loan']:
                hit = True
            if t and t == p.get('card_last4', ''):
                hit = True
            if hit:
                hits.append(i)
        return hits if len(hits) == 1 else []
    def prepare_write():
        if not ready() or s.get('transfer_requested'):
            problem()
            return
        for p in s['products']:
            if p['status'] == 'pending' and p['confirmed']:
                d = datetime.date.fromisoformat(p['date'])
                if not (p['floor'] <= p['amount'] <= p['past_due'] and today <= d <= datetime.date.fromisoformat(p['deadline']) and business(d)) or p['writes'] >= 2:
                    problem()
                    return
                p['writes'] += 1
                vars['write_product'], vars['write_amount'], vars['write_date'] = p['product_id'], p['amount'], p['date']
                vars['route'] = 'promise_write'
                return
