            for later in t['slots'][t['position']+1:]:
                js = resolve(later.get('ref', ''), later['kind'], t['origin'], t['focus'], t['readback_ids'])
                others.extend(js)
            if any(i in others for i in ids):
                t['waiting'] = 'conflict'
                emit('scope', 'Please clarify the corrected terms for the product mentioned more than once.', 'collection_question')
                return
