                t['waiting'] = 'terms'
                emit(t['origin'], 'Please clarify the payment date or whether you accept the stated offer.', 'collection_question')
                return
            values = []
            bad_amount = False
            for i in active:
                p = ps[i]
                a0, d0 = base_terms(p, t['origin'], t['focus'])
                try:
                    a = p['floor'] if q['kind'] == 'too_much' else (p['past_due'] if q.get('full_amount') else (amount(q['amount']) if q.get('amount') else a0))
                except Exception:
                    bad_amount = True
                    break
                raw = q.get('date') or d0
                mode, d, context = parse_date(raw, p['date_context'])
                form = q.get('date_form', 'none')
                if form == 'period' and mode == 'ambiguous':
                    mode = 'period'
                elif (form == 'period' and mode == 'exact') or (form == 'exact' and mode == 'period') or form == 'unknown':
                    mode = 'ambiguous'
                p['date_context'] = context
                if q.get('deadline'):
                    mode, d = 'deadline', p['deadline']
                values.append((i, a, mode, d))
