                p['amount'], p['date'], p['status'], p['confirmed'], p['vague_asked'] = a, day.isoformat(), 'pending', False, False
                if a < p['past_due'] and not p.get('remainder_said'):
                    prefix += 'The rest stays overdue for your ' + p['label'] + '. '
                    p['remainder_said'] = True
            t['position'] += 1
