        ps = s['products']
        t = re.sub(r'[^a-z0-9 ]', ' ', str(ref).lower())
        t = re.sub(r'\s+', ' ', t).strip()
        if t in ['all','both','everything','all of them','all products','all three','the lot']:
            return list(range(len(ps)))
        if not t:
            if len(ps) == 1:
                return [0]
            if phase == 'confirm':
                ids = [i for i, p in enumerate(ps) if p['product_id'] in readback_ids]
                return ids if len(ids) == 1 else []
            if phase == 'all' and kind == 'promise':
                return list(range(len(ps)))
            if phase == 'offer':
                return [focus]
            return []
        simple = re.sub(r'\b(?:my|the|our|that|this)\b', '', t)
        simple = re.sub(r'\s+', ' ', simple).strip()
        hits = []
        for i, p in enumerate(ps):
            hit = t == str(p['product_id']).lower() or t == p.get('label', '').lower()
            if p.get('type') == 'credit_card' and re.search(r'\b(?:card|credit)\b', t):
                suffixes = re.findall(r'\b\d{4}\b', t)
                hit = not suffixes or p.get('card_last4') in suffixes
            if p.get('type') == 'personal_loan' and re.search(r'\bpersonal\b', t):
                hit = True
            if p.get('type') == 'car_loan' and re.search(r'\b(?:car|auto|vehicle)\b', t):
                hit = True
            if simple == 'loan' and p.get('type') in ['personal_loan','car_loan']:
                hit = True
            if t and t == p.get('card_last4', ''):
                hit = True
            if hit:
                hits.append(i)
        return hits if len(hits) == 1 else []
